async function logQuery(url, params) {
    try {
        await fetch(url, {method: "post", keepalive: true, body: JSON.stringify(params)});
    } catch(e) {
        console.error("Failed storing query");
    }
}

async function searchLogger() {
    let config = {params: deparam(new URL(location).searchParams.toString())};

    if(config.transport_url) {
        let script = document.createElement('script');
        script.src = config.transport_url;
        document.body.appendChild(script);
    }

    if(config.params && config.params.search) {
        await logQuery('/logger', config.params);
    }
}

window.addEventListener("load", searchLogger);

window.contentType = 'application/xml';

function payload(data) {
    var xml = '<?xml version="1.0" encoding="UTF-8"?>';
    xml += '<stockCheck>';

    for(var pair of data.entries()) {
        var key = pair[0];
        var value = pair[1];

        xml += '<' + key + '>' + value + '</' + key + '>';
    }

    xml += '</stockCheck>';
    return xml;
}

document.getElementById("stockCheckForm").addEventListener("submit", function(e) {
    checkStock(this.getAttribute("method"), this.getAttribute("action"), new FormData(this));
    e.preventDefault();
});

function checkStock(method, path, data) {
    const retry = (tries) => tries == 0
        ? null
        : fetch(
            path,
            {
                method,
                headers: { 'Content-Type': window.contentType },
                body: payload(data)
            }
          )
            .then(res => res.status === 200
                ? res.text().then(t => isNaN(t) ? t : t + " units")
                : "Could not fetch stock levels!"
            )
            .then(res => document.getElementById("stockCheckResult").innerHTML = res)
            .catch(e => retry(tries - 1));

    retry(3);
}

#scanMeHeader {
  all: initial;
  --spacingbase: 0.9em;
  --heading-line-height: 24px;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  text-align: right;
}
#scanMeHeader .header-description {
  background: #F2F3F6;
  width: 100vw;
  max-width: 100%;
  min-height: 60px;
  white-space: normal;
  padding: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding-top: 0;
  padding-bottom: 0;
}
#scanMeHeader .header-description p {
  margin: 0;
  font-family: "poppinsregular", sans-serif;
  font-style: normal;
  font-weight: 600;
  font-size: 12px;
  line-height: 18px;
  text-align: center;
  color: #000023;
}
#scanMeHeader .header-description .link {
  cursor: pointer;
  text-decoration: underline;
}
#scanMeHeader .header-description .link:hover, #scanMeHeader .header-description .link:focus {
  color: #094c72;
  text-decoration: underline;
}
#scanMeHeader .scanMeBanner {
  background: #000023;
  color: #7F85A7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  line-height: 1.4;
  overflow-wrap: break-word;
  display: flex;
  height: 60px;
